TLM.f("Sancti/11-30",{"officium":"S. Andreæ Apostoli","rule":["ex C1;","Gloria","Credo","Prefatio=Apostolis"],"ruleInherited":["Psalmi Dominica","Antiphonas horas","Psalm5 Vespera=116","Psalm5 Vespera3=138"],"fallback":"Commune/C1","sections":{"Introitus":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."},{"k":"ref","la":"Ps 138:1-2"},{"k":"text","la":"Dómine, probásti me et cognovísti me: tu cognovísti sessiónem meam et resurrectiónem meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Oratio":[{"k":"text","la":"Majestátem tuam, Dómine, supplíciter exorámus: ut, sicut Ecclésiæ tuæ beátus Andréas Apóstolus éxstitit prædicátor et rector; ita apud te sit pro nobis perpétuus intercéssor."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános"},{"k":"ref","la":"Rom 10:10-18"},{"k":"text","la":"Fratres: Corde enim créditur ad justítiam: ore autem conféssio fit ad salútem. Dicit enim Scriptúra: Omnis, qui credit in illum, non confundétur. Non enim est distínctio Judǽi et Græci: nam idem Dóminus ómnium, dives in omnes, qui ínvocant illum. Omnis enim, quicúmque invocáverit nomen Dómini, salvus erit. Quómodo ergo invocábunt, in quem non credidérunt? Aut quómodo credent ei, quem non audiérunt? Quómodo autem áudient sine prædicánte? Quómodo vero prædicábunt, nisi mittántur? sicut scriptum est: Quam speciósi pedes evangelizántium pacem, evangelizándum bona! Sed non omnes obédiunt Evangélio. Isaías enim dicit: Dómine, quis crédidit audítui nostro? Ergo fides ex audítu, audítus autem per verbum Christi. Sed dico: Numquid non audiérunt? Et quidem in omnem terram exívit sonus eórum, et in fines orbis terræ verba eórum."}],"Graduale":[{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine."},{"k":"text","la":"Pro pátribus tuis nati sunt tibi fílii: proptérea pópuli confitebúntur tibi.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"text","la":"Diléxit Andréam Dóminus in odórem suavitátis. Allelúja.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 4:18-22"},{"k":"text","la":"In illo témpore: Ambulans Jesus juxta mare Galilǽæ, vidit duos fratres, Simónem, qui vocátur Petrus, et Andréam fratrem ejus, mitténtes rete in mare - erant enim piscatóres - et ait illis: Veníte post me, et fáciam vos fíeri piscatóres hóminum. At illi contínuo, relíctis rétibus, secúti sunt eum. Et procédens inde, vidit álios duos fratres, Jacóbum Zebedæi et Joánnem, fratrem ejus, in navi cum Zebedæo patre eórum reficiéntes rétia sua: et vocávit eos. Illi autem statim, relíctis rétibus et patre, secúti sunt eum."}],"Offertorium":[{"k":"ref","la":"Ps 138:17"},{"k":"text","la":"Mihi autem nimis honoráti sunt amíci tui, Deus: nimis confortátus est principátus eórum."}],"Secreta":[{"k":"text","la":"Sacrificium nostrum tibi, Dómine, quǽsumus, beáti Andréæ Apóstoli precátio sancta concíliet: ut, in cujus honóre sollémniter exhibétur, ejus méritis efficiátur accéptum."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 4:19-20"},{"k":"text","la":"Veníte post me: fáciam vos fíeri piscatóres hóminum; at illi contínuo, relíctis rétibus, secúti sunt Dóminum."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, divína mystéria, beáti Andréæ Apóstoli festivitáte lætántes: quæ, sicut tuis Sanctis ad glóriam, ita nobis, quǽsumus, ad véniam prodésse perfícias."},{"k":"macro","name":"Per Dominum"}]},"hr":{"4ce2969ae90d1d66":{"t":"Ps 138, 17, Ps 138, 1-2\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove. (Ps 138, 1-2) Gospodine, ti si me kušao i spoznao, tebi je poznat moj počinak i moje uskrsnuće.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 138, 17) Nadasve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno je utvrđeno kneževstvo njihovo. (Ps. 133, 1). Gospodine, Ti sj me kušao i spoznaoi; Tebi je poznat moj počinak i moje ustajanje. Slava Ocu . . . Veoma ...","knRef":"Kniewald 1942, str. 458–459 (snimka 230) (OCR)"},"ae9291311e67b170":{"t":"<i>Pomolimo se</i>.\nSmjerno molimo tvoje veličanstvo, Gospodine, kao što je blaženi Andrija apostol Crkvi tvojoj bio propovjednik i upravitelj, tako da nam kod tebe uvijek bude zagovornik.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Smjerno molimo Tvoje veličanstvo. Gospodine, kao što je blaženi Andrija, apostol. Crkvi Tvojoj propovijedao i njome upravljao, tako da naš kod Tebe uvijek zagovara, po G- _n- _","knRef":"Kniewald 1942, str. 446–447 (snimka 224) (OCR)"},"d36a86a61c51dfad":{"t":"Rim 10, 10-18\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Srcem se vjeruje za opravdanje, a ustima se ispovijeda vjera za spas. Jer Pismo kaže: »Neće se postidjeti nijedan koji vjeruje u njega.« A nema razlike među Židovom i Grkom, jer je isti Gospodin svih bogat za sve koji ga prizivaju. A spasit će se svaki koji god bude prizvao Gospodina. Nego, kako će prizivati onog u koga nisu vjerovali? Ili kako će vjerovati u onoga o kojemu nisu čuli? Kako će čuti bez propovjednika? Kako će propovijedati ako nisu poslani? Kao što je pisano: »Kako su krasne noge onih koji navješćuju mir, koji navješćuju dobro!« Ali se svi ne pokoravaju evanđelju, kako kaže Izaija: »Gospodine, tko vjeruje našemu propovijedanju?« Dakle, vjera je od propovijedanja, a propovijeda se po Kristovoj zapovijedi. Nego pitam vas: Zar nisu čuli? Ta po svoj se zemlji razliježe njihov glas i njihove riječi do na kraj svijeta."},"4e1c40c9b6c9cd64":{"t":"Ps 44, 17-18\nPostavit ćeš ih za knezove nad svom zemljom, spominjat će tvoje ime, Gospodine. Mjesto tvojih otaca rodit će ti se sinovi, zato će te narodi slaviti.\n\n<i>Aleluja</i>, <i>aleluja</i>.\nLjubio je Gospodin Andriju kao ugodni miris. <i>Aleluja</i>.","kn":"(Ps. 44, 17, 18). Postavit ćeš ih knezovima po svoj zemlji, sjećat će se imena Tvoga, Gospodine! Mjesto otaca bit će sinovi Tvoji, zato će Te narodi slaviti.\n\nAleluja, aleluja. Ljubio je Gospodin. Andriju kao miris blagoduli, aleluja. ■, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 616–617 (snimka 309) (OCR)"},"b36ea20178aca6a4":{"t":"Mt 4, 18-22\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme kad je Isus hodao uz obalu Genezaretskoga mora, vidje dva brata, Šimuna koji se zove Petar i njegova brata Andriju, gdje bacaju u more mreže (jer su bili ribari). I pozove ih: »Dođite za mnom i učinit ću vas ribarima ljudi!« Oni odmah ostave mreže i podu za njim. – I kad je pošao dalje, vidio je druga dva brata Jakova Zebedejeva i brata mu Ivana gdje u lađi sa svojim ocem popravljaju svoje mreže i pozove ih. I oni odmah ostave mreže i oca i pođu za njim.","kn":"t Slijedi sveto evanđelje po Mateju (4, 18-22). U ono vrijeme, kad je Isus hodao uz obalu Genezaretskoga mora, vidje dva brata, Simuna, koji :se zove Petar, i njegova brata Andriju, gdje bacaju u more mreže (jer su bili ribari). I pozove ih: Dođite za mnom i učinit ću vas ribarima, ljudi! Oni odmah ostave mreže i /pođu za njim, . I kad' je pošao dalje, vidio je druga dva brata, 'Jaikova ' Zebedejeva i brata mu Ivana, gdje u lađi sa svojim ocem popravljaju svoje mreže,, i pozove ih. I oni odmah Ostave mreže i oca i pođu, za njim. , '","knRef":"Kniewald 1942, str. 448–449 (snimka 225) (OCR)"},"8bade162dbdb175e":{"t":"Ps 138, 17\nNada sve častim tvoje prijatelje, Bože, jer je velika uloga vlasti njihove.","kn":"(Ps. 138, 17). Veoma častim prijatelje Tvoje, Bože, silno se utvrdi kneževstvo njihovo!","knRef":"Kniewald 1942, str. 742–743 (snimka 372) (OCR)"},"25c26a610bff5c45":{"t":"Neka ti, Gospodine, budu ugodne naše žrtve po zagovoru svetog Andrije apostola da ti se svide po zaslugama onih kojima ih na čast svečano prinosimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Neka Ti, Gospodine, budu ugodne naše žrtve po zagovoru sv; apostola Andrije, da Ti budu prijatne zaslugama onih, kojima ih na čast* svečano prinosimo. Po Gospodinu...","knRef":"Kniewald 1942, str. 448–449 (snimka 225) (OCR)"},"fdbfd5e8960de5c2":{"t":"Uistinu je dostojno, i pravedno, pravo i spasonosno tebe, Gospodine, vječni Pastiru, smjerno moliti da stado svoje ne ostaviš, nego da ga po svojim blaženim apostolima neprestano štitiš i čuvaš, da njime ravnaju isti poglavari, koje si mu postavio na čelo kao pastire i namjesnike svoga djela. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno. Tebe, Gospodine, vječni Pastiru, smjerno moliti, da ne ostaviš svoga stada, nego’ da ga po blaženim svojim apostolima sveudiljnom zaštitom čuvaš, te Tvojim stadom upravljaju isti vođe, koje si Ti odredio da ga vode kao pastiri i namjesnici Tvoga djelovanja. I toga radi pjevamo pjesmu slave Tvoje s anđelima i s arkanđelima, s prijestolima i s gospodstvima i sa svom silom nebeske vojske govoreći bez prestanka:","knRef":"Kniewald 1942, str. 618–619 (snimka 310) (OCR)"},"36b3d308a2a470b8":{"t":"Mt 4, 19-20\nPođite za mnom, učinit ću vas ribarima ljudi! A oni ostave mreže i pođu odmah za Gospodinom.","kn":"(Mt. 4). Pođite za mnom, učinit čti vas ribarima ljudi; a oni ostavivši mreže i lađu, pođoše odmah za Gospodinom.","knRef":"Kniewald 1942, str. 448–449 (snimka 225) (OCR)"},"7b3b583ae984d9d8":{"t":"<i>Pomolimo se</i>.\nPrimismo, Gospodine, božanstvene tajne veseleći se blagdanu svetoga Andrije, daj da budu nama na oproštenje, kao što su na čast tvojim svecima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primismo, Gospodine, božanstvene tajne, veseleći se na praznik sv. Andčije: daj da budu naina na oproštenje, kao što su na čast' Tvojim svecima. Po G. n.","knRef":"Kniewald 1942, str. 448–449 (snimka 225) (OCR)"}}});
